  <script>
    const courses = [
      { category: 'Featured', title: 'Kickstart your Creativity with Procreate: 20 Fun Drawings for Beginners and Beyond', instructor: 'Lisa Bardot', students: '120,392', duration: '6h 12m', img: 'https://images.unsplash.com/photo-1517694712202-14dd9538aa97?auto=format&fit=crop&w=900&q=80' },
      { category: 'Marketing', title: 'Social Media Content Creation in Canva: From Beginner to Advanced', instructor: 'Mina Lee', students: '65,024', duration: '4h 45m', img: 'https://images.unsplash.com/photo-1460925895917-afdab827c52f?auto=format&fit=crop&w=900&q=80' },
