      { category: 'UI/UX', title: 'Figma UI UX Design Advanced: Become a Pro', instructor: 'Daniel Scott', students: '83,243', duration: '11h 20m', img: 'https://images.unsplash.com/photo-1558655146-9f40138edfeb?auto=format&fit=crop&w=900&q=80' },
      { category: 'Drawing & Painting', title: "How to Draw: A Beginner's Guide", instructor: 'Marco Bucci', students: '92,350', duration: '5h 05m', img: 'https://images.unsplash.com/photo-1452802447250-470a88ac82bc?auto=format&fit=crop&w=900&q=80' },
      { category: 'Featured', title: 'Learn Video Editing With Premiere Pro For Beginners', instructor: 'Jordan Mae', students: '57,611', duration: '7h 10m', img: 'https://images.unsplash.com/photo-1574717024653-61fd2cf4d44d?auto=format&fit=crop&w=900&q=80' },
      { category: 'Music', title: 'Music Production Essentials in Ableton', instructor: 'Kai Rivers', students: '39,102', duration: '8h 02m', img: 'https://images.unsplash.com/photo-1511379938547-c1f69419868d?auto=format&fit=crop&w=900&q=80' },
      { category: 'Animation', title: '2D Character Animation Fundamentals', instructor: 'Elena Torres', students: '44,531', duration: '6h 48m', img: 'https://images.unsplash.com/photo-1604871000636-074fa5117945?auto=format&fit=crop&w=900&q=80' }
    ];

    const grid = document.getElementById('course-grid');
    const tabs = [...document.querySelectorAll('.tab')];

    function renderCourses(category) {
      const selected = category === 'Featured'
        ? courses.filter(c => c.category === 'Featured' || c.title.includes('Figma') || c.title.includes('How to Draw') || c.title.includes('Canva') || c.title.includes('Landscapes'))
        : courses.filter(c => c.category === category);

      const list = selected.slice(0, 6).length ? selected.slice(0, 6) : courses.slice(0, 6);

      grid.innerHTML = list.map(course => `
        <article class="card course-card">
          <img src="${course.img}" alt="${course.title}">
          <div class="course-body">
            <h3 class="course-title">${course.title}</h3>
            <p class="course-meta">${course.instructor} · ${course.students} students · ${course.duration}</p>
          </div>
        </article>
      `).join('');
    }

    tabs.forEach(tab => tab.addEventListener('click', () => {
      tabs.forEach(item => item.setAttribute('aria-selected', 'false'));
      tab.setAttribute('aria-selected', 'true');
      renderCourses(tab.dataset.category);
    }));

    renderCourses('Featured');

    const faqItems = [...document.querySelectorAll('.faq-item')];
    faqItems.forEach(item => {
      const button = item.querySelector('.faq-q');
      button.addEventListener('click', () => {
        const isOpen = item.classList.contains('open');
        faqItems.forEach(i => {
          i.classList.remove('open');
          i.querySelector('.faq-q').setAttribute('aria-expanded', 'false');
        });
        if (!isOpen) {
          item.classList.add('open');
          button.setAttribute('aria-expanded', 'true');
        }
      });
    });

    const track = document.getElementById('teacher-track');
    document.getElementById('teachers-prev').addEventListener('click', () => track.scrollBy({ left: -280, behavior: 'smooth' }));
    document.getElementById('teachers-next').addEventListener('click', () => track.scrollBy({ left: 280, behavior: 'smooth' }));

    document.getElementById('google-signup').addEventListener('click', () => alert('Google OAuth flow would start here.'));
    document.getElementById('email-signup').addEventListener('click', () => alert('Email sign-up form would open here.'));
  </script>
